    a = a % m
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    return None

inverses = [modinv(n, 41) for n in numbers]

char_map = {}
for i in range(26):
    char_map[i+1] = chr(ord('a') + i)
for i in range(10):
    char_map[27+i] = str(i)
char_map[37] = ' '

result = ''.join(char_map.get(v, f'[{v}]') for v in inverses)

# Decode leetspeak
leet = {'1':'i', '3':'e', '4':'a', '5':'s', '6':'g', '8':'b', '0':'o'}
